static void TrainModel(string dataPath, string modelPath)
{
    var mlContext = new MLContext(seed: 42);

    IDataView rawData = mlContext.Data.LoadFromTextFile<CustomerDataRaw>(
        dataPath, hasHeader: true, separatorChar: ',');

    // Map "Yes"/"No" string → boolean Label column
    var labelKeys = new[] { "Yes", "No" };
    var labelValues = new[] { true, false };
    var labelPipeline = mlContext.Transforms.Conversion.MapValue(
        "Label", labelKeys, labelValues, inputColumnName: nameof(CustomerDataRaw.Churned));

    var data = labelPipeline.Fit(rawData).Transform(rawData);

    var pipeline = mlContext.Transforms.Categorical.OneHotEncoding("RegionEncoded", nameof(CustomerDataRaw.Region))
        .Append(mlContext.Transforms.Concatenate("Features",
            nameof(CustomerDataRaw.Age),
            nameof(CustomerDataRaw.Income),
            "RegionEncoded",
            nameof(CustomerDataRaw.PurchaseHistory)))
        .Append(mlContext.Transforms.NormalizeMinMax("Features"))
        .Append(mlContext.BinaryClassification.Trainers.SdcaLogisticRegression(
            labelColumnName: "Label", featureColumnName: "Features"));

    long rowCount = data.GetColumn<bool>("Label").LongCount();

    ITransformer model;
    if (rowCount >= 10)
    {
        var split = mlContext.Data.TrainTestSplit(data, testFraction: 0.2, seed: 42);
        model = pipeline.Fit(split.TrainSet);
        var predictions = model.Transform(split.TestSet);
        var metrics = mlContext.BinaryClassification.Evaluate(predictions, labelColumnName: "Label");
        Console.WriteLine($"Model metrics — AUC: {metrics.AreaUnderRocCurve:F4}, " +
                          $"F1: {metrics.F1Score:F4}, Accuracy: {metrics.Accuracy:F4}");
    }
    else
    {
        Console.WriteLine($"Dataset has only {rowCount} rows — training on all data (add more rows for train/test evaluation).");
        model = pipeline.Fit(data);
    }

    mlContext.Model.Save(model, data.Schema, modelPath);
    Console.WriteLine($"Model saved to {modelPath}");
}

